// Root and Provider

// Actions
export { FilterActions as Actions } from './components/actions/filter-actions'
// Item components
export {
  FilterItem as Item,
  useFilterItemContext,
} from './components/item/filter-item'
export { FilterOperator as Operator } from './components/item/filter-operator'
export { FilterRemove as Remove } from './components/item/filter-remove'
export { FilterSubject as Subject } from './components/item/filter-subject'
export { FilterValue as Value } from './components/item/filter-value'
// List
export { FilterList as List } from './components/list/filter-list'
export { FilterListMobileContainer as ListMobileContainer } from './components/list/filter-list-mobile-container'
// Menu and Trigger
export { FilterMenu as Menu } from './components/menu/filter-menu'
export { FilterProvider as Provider } from './components/provider/filter-provider'
// Context exports
export {
  FilterContext as Context,
  useFilterActions,
  useFilterColumn,
  useFilterContext,
  useFilterEntityName,
  useFilterLocale,
  useFilterStrategy,
  useFilterVariant,
} from './components/root/filter-context'
export { FilterRoot as Root } from './components/root/filter-root'
export { FilterTrigger as Trigger } from './components/trigger/filter-trigger'

// Value utilities (for advanced usage)
export {
  // Menu creators
  createMultiOptionMenu,
  // Render functions for custom item rendering
  createOptionItemRenderer,
  createOptionMenu,
  createSelectableMenu,
  // Text filter utilities
  createTextFilterItems,
  createTextItemRenderer,
  // Controllers
  FilterValueDateController,
  FilterValueNumberController,
  // Shared editor content components (for custom menu implementations)
  OptionEditorContent,
  renderOptionItem,
  renderTextItem,
  TextEditorContent,
} from './components/value'

'use client'

import { type ComponentPropsWithoutRef, forwardRef, type Ref } from 'react'
import { useIsMobile } from '@/hooks/use-mobile'
import { cn } from '@/lib/utils'

export interface FilterRootProps extends ComponentPropsWithoutRef<'div'> {
  ref?: Ref<HTMLDivElement>
}

/**
 * Layout container for filter components.
 * Must be wrapped with `Filter.Provider` to access filter context.
 * Renders a `<div>` element.
 *
 * Documentation: [Bazza UI Filter](https://bazza-ui.com/docs/components/filter)
 */
function FilterRootImpl(
  { children, className, ...props }: FilterRootProps,
  ref: Ref<HTMLDivElement>,
) {
  const isMobile = useIsMobile()

  return (
    <div
      ref={ref}
      data-slot="filter-root"
      data-mobile={isMobile}
      className={cn('flex w-full items-start justify-between gap-2', className)}
      {...props}
    >
      {children}
    </div>
  )
}

FilterRootImpl.displayName = 'FilterRoot'

/**
 * Layout container for filter components.
 * Must be wrapped with `Filter.Provider` to access filter context.
 * Renders a `<div>` element.
 *
 * Documentation: [Bazza UI Filter](https://bazza-ui.com/docs/components/filter)
 */
const FilterRoot = forwardRef(FilterRootImpl)

export { FilterRoot }

export namespace FilterRoot {
  export type Props = FilterRootProps
}

'use client'

import type {
  Column,
  DataTableFilterActions,
  FilterStrategy,
  FiltersState,
  Locale,
} from '@bazza-ui/filters'
import {
  FilterContext,
  type FilterContextValue,
  type FilterVariant,
} from '../root/filter-context'

export interface FilterProviderProps<TData = unknown> {
  columns: Column<TData>[]
  filters: FiltersState
  actions: DataTableFilterActions
  strategy: FilterStrategy
  locale?: Locale
  entityName?: string
  variant?: FilterVariant
  children: React.ReactNode
}

export function FilterProvider<TData>({
  columns,
  filters,
  actions,
  strategy,
  locale = 'en',
  entityName,
  variant,
  children,
}: FilterProviderProps<TData>) {
  const contextValue: FilterContextValue<TData> = {
    columns,
    filters,
    actions,
    strategy,
    locale,
    entityName,
    variant,
  }

  return (
    <FilterContext.Provider value={contextValue as FilterContextValue}>
      {children}
    </FilterContext.Provider>
  )
}

export namespace FilterProvider {
  export type Props<TData = unknown> = FilterProviderProps<TData>
}

'use client'

import type {
  Column,
  DataTableFilterActions,
  FilterStrategy,
  FiltersState,
  Locale,
} from '@bazza-ui/filters'
import { createContext, useContext, useMemo } from 'react'

export type FilterVariant = 'default' | 'clean'

export interface FilterContextValue<TData = unknown> {
  columns: Column<TData>[]
  filters: FiltersState
  actions: DataTableFilterActions
  strategy: FilterStrategy
  locale: Locale
  entityName?: string
  variant?: FilterVariant
}

export const FilterContext = createContext<FilterContextValue | null>(null)

export function useFilterContext<TData = unknown>(): FilterContextValue<TData> {
  const context = useContext(FilterContext)
  if (!context) {
    throw new Error('useFilterContext must be used within a FilterProvider')
  }
  return context as FilterContextValue<TData>
}

export function useFilterColumn<TData = unknown>(
  columnId: string,
): Column<TData> | undefined {
  const { columns } = useFilterContext<TData>()
  return useMemo(
    () => columns.find((col) => col.id === columnId),
    [columns, columnId],
  )
}

export function useFilterActions() {
  const { actions } = useFilterContext()
  return actions
}

export function useFilterStrategy() {
  const { strategy } = useFilterContext()
  return strategy
}

export function useFilterLocale() {
  const { locale } = useFilterContext()
  return locale
}

export function useFilterEntityName() {
  const { entityName } = useFilterContext()
  return entityName
}

export function useFilterVariant() {
  const { variant } = useFilterContext()
  return variant
}

export namespace FilterContext {
  export type Value<TData = unknown> = FilterContextValue<TData>
}

'use client'

import type {
  Column,
  DataTableFilterActions,
  FilterModel,
  FilterStrategy,
  FiltersState,
  Locale,
} from '@bazza-ui/filters'
import {
  isBooleanColumn,
  isDateColumn,
  isMultiOptionColumn,
  isNumberColumn,
  isOptionColumn,
  isTextColumn,
} from '@bazza-ui/filters'
import type {
  ItemDef,
  ItemRenderParams,
  NodeDef,
  SubmenuDef,
  SubmenuRenderParams,
} from '@bazza-ui/react'
import * as React from 'react'
import { isValidElement, memo, useMemo } from 'react'
import { DropdownMenu, LabelWithBreadcrumbs } from '@/registry/ui/dropdown-menu'
import {
  type FilterVariant,
  useFilterContext,
  useFilterVariant,
} from '../root/filter-context'
import { FilterTrigger } from '../trigger/filter-trigger'
import {
  createMultiOptionMenu,
  createOptionMenu,
  FilterValueDateController,
  FilterValueNumberController,
  TextEditorContent,
} from '../value'

// ============================================================================
// Submenu Renderer Helper
// ============================================================================

/**
 * Renders an icon for a column, handling both element and component types.
 */
function renderColumnIcon(
  icon: React.ReactElement | React.ElementType | undefined,
): React.ReactNode {
  if (!icon) return null

  return (
    <div className="size-4 flex items-center justify-center">
      {isValidElement(icon) ? (
        icon
      ) : (
        <DropdownMenu.Icon>
          {React.createElement(
            icon as React.ComponentType<{ className?: string }>,
            {
              className:
                'size-4 shrink-0 text-muted-foreground group-data-[highlighted]/row:text-primary',
            },
          )}
        </DropdownMenu.Icon>
      )}
    </div>
  )
}

/**
 * Creates a render function for a submenu with nodes (DataSurface).
 */
function createSubmenuRenderer(
  id: string,
  title: string,
  icon: React.ReactElement | React.ElementType | undefined,
  nodes: NodeDef[],
  inputPlaceholder = 'Search...',
): (params: SubmenuRenderParams) => React.ReactNode {
  return ({ context }: SubmenuRenderParams) => {
    return (
      <DropdownMenu.Submenu key={id}>
        <DropdownMenu.SubmenuTrigger value={id} className="group/row">
          <div className="flex items-center gap-2 min-w-0">
            {renderColumnIcon(icon)}
            <LabelWithBreadcrumbs
              label={title}
              breadcrumbs={
                context.isDeepSearchResult ? context.breadcrumbs : undefined
              }
            />
          </div>
        </DropdownMenu.SubmenuTrigger>
        <DropdownMenu.Portal>
          <DropdownMenu.Positioner sideOffset={-2}>
            <DropdownMenu.Popup>
              <DropdownMenu.DataSurface content={nodes}>
                <DropdownMenu.DataInput placeholder={inputPlaceholder} />
                <DropdownMenu.DataList virtualized>
                  <DropdownMenu.Empty>No matching options.</DropdownMenu.Empty>
                </DropdownMenu.DataList>
              </DropdownMenu.DataSurface>
            </DropdownMenu.Popup>
          </DropdownMenu.Positioner>
        </DropdownMenu.Portal>
      </DropdownMenu.Submenu>
    )
  }
}

/**
 * Creates a render function for a submenu with custom content (for date/number controllers).
 */
function createCustomSubmenuRenderer(
  id: string,
  title: string,
  icon: React.ReactElement | React.ElementType | undefined,
  content: React.ReactNode,
): (params: SubmenuRenderParams) => React.ReactNode {
  return ({ context }: SubmenuRenderParams) => {
    return (
      <DropdownMenu.Submenu key={id}>
        <DropdownMenu.SubmenuTrigger value={id} className="group/row">
          <div className="flex items-center gap-2 min-w-0">
            {renderColumnIcon(icon)}
            <LabelWithBreadcrumbs
              label={title}
              breadcrumbs={
                context.isDeepSearchResult ? context.breadcrumbs : undefined
              }
            />
          </div>
        </DropdownMenu.SubmenuTrigger>
        <DropdownMenu.Portal>
          <DropdownMenu.Positioner sideOffset={-2}>
            <DropdownMenu.Popup className="w-full">
              <DropdownMenu.Surface>{content}</DropdownMenu.Surface>
            </DropdownMenu.Popup>
          </DropdownMenu.Positioner>
        </DropdownMenu.Portal>
      </DropdownMenu.Submenu>
    )
  }
}

// ============================================================================
// Menu Node Creators
// ============================================================================

function createDateSubmenuDef<TData>({
  filter,
  column,
  actions,
  locale = 'en',
  strategy,
}: {
  filter: FilterModel<'date'>
  column: Column<TData, 'date'>
  actions: DataTableFilterActions
  locale?: Locale
  strategy: FilterStrategy
}): SubmenuDef {
  return {
    kind: 'submenu',
    id: column.id,
    value: column.displayName,
    render: createCustomSubmenuRenderer(
      column.id,
      column.displayName,
      column.icon,
      <FilterValueDateController
        filter={filter}
        column={column}
        actions={actions}
        strategy={strategy}
        locale={locale}
      />,
    ),
  }
}

function createNumberSubmenuDef<TData>({
  filter,
  column,
  actions,
  locale = 'en',
  strategy,
}: {
  filter: FilterModel<'number'>
  column: Column<TData, 'number'>
  actions: DataTableFilterActions
  locale?: Locale
  strategy: FilterStrategy
}): SubmenuDef {
  return {
    kind: 'submenu',
    id: column.id,
    value: column.displayName,
    render: createCustomSubmenuRenderer(
      column.id,
      column.displayName,
      column.icon,
      <FilterValueNumberController
        filter={filter}
        column={column}
        actions={actions}
        strategy={strategy}
        locale={locale}
      />,
    ),
  }
}

function createOptionSubmenuDef<TData>({
  column,
  actions,
  filter,
  locale,
  strategy,
}: {
  column: Column<TData, 'option'>
  actions: DataTableFilterActions
  filter?: FilterModel<'option'>
  locale: Locale
  strategy: FilterStrategy
}): SubmenuDef {
  const { nodes } = createOptionMenu({
    column,
    actions,
    filter,
    locale,
    strategy,
  })
  return {
    kind: 'submenu',
    id: column.id,
    value: column.displayName,
    nodes,
    render: createSubmenuRenderer(
      column.id,
      column.displayName,
      column.icon,
      nodes,
      `Search ${column.displayName.toLowerCase()}...`,
    ),
  }
}

function createMultiOptionSubmenuDef<TData>({
  column,
  actions,
  filter,
  locale,
  strategy,
}: {
  column: Column<TData, 'multiOption'>
  actions: DataTableFilterActions
  filter?: FilterModel<'multiOption'>
  locale: Locale
  strategy: FilterStrategy
}): SubmenuDef {
  const { nodes } = createMultiOptionMenu({
    column,
    actions,
    filter,
    locale,
    strategy,
  })
  return {
    kind: 'submenu',
    id: column.id,
    value: column.displayName,
    nodes,
    render: createSubmenuRenderer(
      column.id,
      column.displayName,
      column.icon,
      nodes,
      `Search ${column.displayName.toLowerCase()}...`,
    ),
  }
}

/**
 * Text submenu content component that renders a submenu with TextEditorContent.
 */
function TextSubmenuContent<TData>({
  id,
  title,
  icon,
  column,
  actions,
  context,
}: {
  id: string
  title: string
  icon: React.ReactElement | React.ElementType | undefined
  column: Column<TData, 'text'>
  actions: DataTableFilterActions
  context: SubmenuRenderParams['context']
}) {
  return (
    <DropdownMenu.Submenu key={id}>
      <DropdownMenu.SubmenuTrigger value={id} className="group/row">
        <div className="flex items-center gap-2 min-w-0">
          {renderColumnIcon(icon)}
          <LabelWithBreadcrumbs
            label={title}
            breadcrumbs={
              context.isDeepSearchResult ? context.breadcrumbs : undefined
            }
          />
        </div>
      </DropdownMenu.SubmenuTrigger>
      <DropdownMenu.Portal>
        <DropdownMenu.Positioner sideOffset={-2} align="start" alignOffset={-3}>
          <DropdownMenu.Popup>
            <TextEditorContent
              column={column as Column<unknown, 'text'>}
              actions={actions}
            />
          </DropdownMenu.Popup>
        </DropdownMenu.Positioner>
      </DropdownMenu.Portal>
    </DropdownMenu.Submenu>
  )
}

function createTextSubmenuDef<TData>({
  column,
  actions,
}: {
  column: Column<TData, 'text'>
  actions: DataTableFilterActions
}): SubmenuDef {
  return {
    kind: 'submenu',
    id: column.id,
    value: column.displayName,
    // Text menus need controlled search - we'll handle this with a custom renderer
    render: (params: SubmenuRenderParams) => {
      return (
        <TextSubmenuContent
          id={column.id}
          title={column.displayName}
          icon={column.icon}
          column={column as Column<unknown, 'text'>}
          actions={actions}
          context={params.context}
        />
      )
    },
  }
}

function createBooleanItemDef<TData>({
  column,
  actions,
}: {
  column: Column<TData, 'boolean'>
  actions: DataTableFilterActions
}): ItemDef {
  return {
    kind: 'item',
    id: `filter-value-${column.id}`,
    value: column.displayName,
    onSelect: () => {
      actions.setFilterValue(column, [false])
    },
    render: ({ context }: ItemRenderParams) => {
      return (
        <DropdownMenu.Item
          key={column.id}
          value={column.id}
          className="group/row"
        >
          {renderColumnIcon(column.icon)}
          <LabelWithBreadcrumbs
            label={column.displayName}
            breadcrumbs={
              context.isDeepSearchResult ? context.breadcrumbs : undefined
            }
          />
        </DropdownMenu.Item>
      )
    },
  }
}

// ============================================================================
// FilterMenu Component
// ============================================================================

export interface FilterMenuProps<TData = unknown> {
  columns?: Column<TData>[]
  filters?: FiltersState
  actions?: DataTableFilterActions
  strategy?: FilterStrategy
  locale?: Locale
  children?: React.ReactElement
  rootProps?: Partial<
    Omit<React.ComponentProps<typeof DropdownMenu.Root>, 'children'>
  >
  variant?: FilterVariant
}

function __FilterMenu<TData>({
  columns: columnsProp,
  filters: filtersProp,
  actions: actionsProp,
  strategy: strategyProp,
  locale: localeProp,
  children,
  rootProps,
  variant: variantProp,
}: FilterMenuProps<TData>) {
  // Get values from context if not provided as props
  const context = useFilterContext<TData>()
  const contextVariant = useFilterVariant()

  const columns = columnsProp ?? context.columns
  const filters = filtersProp ?? context.filters
  const actions = actionsProp ?? context.actions
  const strategy = strategyProp ?? context.strategy
  const locale = localeProp ?? context.locale ?? 'en'
  const variant = variantProp ?? contextVariant

  const visibleColumns = useMemo(
    () => columns.filter((c) => !c.hidden),
    [columns],
  )

  const visibleFilters = useMemo(
    () =>
      filters.filter((f) => visibleColumns.find((c) => c.id === f.columnId)),
    [filters, visibleColumns],
  )

  const hasVisibleFilters = visibleFilters.length > 0

  const nodes: NodeDef[] = useMemo(
    () =>
      columns.map((column): NodeDef => {
        if (isTextColumn(column)) {
          return createTextSubmenuDef({
            column,
            actions,
          })
        }

        if (isDateColumn(column)) {
          const dateFilter = filters.find(
            (f): f is FilterModel<'date'> =>
              f.columnId === column.id && f.type === 'date',
          )
          return createDateSubmenuDef({
            filter: dateFilter as FilterModel<'date'>,
            column,
            actions,
            locale,
            strategy,
          })
        }

        if (isNumberColumn(column)) {
          const numberFilter = filters.find(
            (f): f is FilterModel<'number'> =>
              f.columnId === column.id && f.type === 'number',
          )
          return createNumberSubmenuDef({
            filter: numberFilter as FilterModel<'number'>,
            column,
            actions,
            locale,
            strategy,
          })
        }

        if (isBooleanColumn(column)) {
          return createBooleanItemDef({
            column,
            actions,
          })
        }

        if (isOptionColumn(column)) {
          const optionFilter = filters.find(
            (f): f is FilterModel<'option'> =>
              f.columnId === column.id && f.type === 'option',
          )
          return createOptionSubmenuDef({
            column,
            actions,
            filter: optionFilter,
            locale,
            strategy,
          })
        }

        if (isMultiOptionColumn(column)) {
          const multiOptionFilter = filters.find(
            (f): f is FilterModel<'multiOption'> =>
              f.columnId === column.id && f.type === 'multiOption',
          )
          return createMultiOptionSubmenuDef({
            column,
            actions,
            filter: multiOptionFilter,
            locale,
            strategy,
          })
        }

        // Fallback for any unknown column types
        return {
          kind: 'submenu',
          id: column.id,
          value: column.displayName,
          render: createSubmenuRenderer(
            column.id,
            column.displayName,
            column.icon,
            [],
          ),
        } satisfies SubmenuDef
      }),
    [columns, filters, actions, locale, strategy],
  )

  const triggerElement = children ?? (
    <FilterTrigger
      hasVisibleFilters={hasVisibleFilters}
      locale={locale}
      variant={variant}
    />
  )

  return (
    <DropdownMenu.Root {...rootProps}>
      <DropdownMenu.Trigger render={triggerElement} />
      <DropdownMenu.Portal>
        <DropdownMenu.Positioner align="start">
          <DropdownMenu.Popup>
            <DropdownMenu.DataSurface content={nodes}>
              <DropdownMenu.DataInput placeholder="Search filters..." />
              <DropdownMenu.DataList>
                {({ nodes: displayNodes, renderNode }) =>
                  displayNodes.map(renderNode)
                }
              </DropdownMenu.DataList>
              <DropdownMenu.Empty>No matching filters.</DropdownMenu.Empty>
            </DropdownMenu.DataSurface>
          </DropdownMenu.Popup>
        </DropdownMenu.Positioner>
      </DropdownMenu.Portal>
    </DropdownMenu.Root>
  )
}

export const FilterMenu = memo(__FilterMenu) as typeof __FilterMenu

export namespace FilterMenu {
  export type Props<TData = unknown> = FilterMenuProps<TData>
}

'use client'

import { type Locale, t } from '@bazza-ui/filters'
import { ListFilterIcon } from 'lucide-react'
import { type ComponentPropsWithoutRef, forwardRef } from 'react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import type { FilterVariant } from '../root/filter-context'

export interface FilterTriggerProps extends ComponentPropsWithoutRef<'button'> {
  hasVisibleFilters?: boolean
  locale?: Locale
  variant?: FilterVariant
}

/**
 * A button that opens the filter menu.
 * Renders a `<button>` element.
 *
 * This component is designed to be used with `DropdownMenu.Trigger`'s `render` prop.
 *
 * Documentation: [Bazza UI Filter](https://bazza-ui.com/docs/components/filter)
 */
const FilterTrigger = forwardRef<HTMLButtonElement, FilterTriggerProps>(
  (
    {
      className,
      children,
      hasVisibleFilters = false,
      locale = 'en',
      variant,
      ...props
    },
    ref,
  ) => {
    return (
      <Button
        ref={ref}
        data-slot="filter-trigger"
        data-state={hasVisibleFilters ? 'has-filters' : 'empty'}
        variant="outline"
        className={cn('h-7', hasVisibleFilters && 'w-fit !px-2', className)}
        {...props}
      >
        {children ?? (
          <>
            <ListFilterIcon className="size-4" />
            {!hasVisibleFilters && <span>{t('filter', locale)}</span>}
          </>
        )}
      </Button>
    )
  },
)

FilterTrigger.displayName = 'FilterTrigger'

export { FilterTrigger }

export namespace FilterTrigger {
  export type Props = FilterTriggerProps
}

'use client'

import { type Column, type FilterModel, getColumn } from '@bazza-ui/filters'
import {
  type ComponentPropsWithoutRef,
  forwardRef,
  type ReactNode,
} from 'react'
import { cn } from '@/lib/utils'
import { useFilterContext } from '../root/filter-context'

type FilterListRenderProps<TData = unknown> = {
  filter: FilterModel
  column: Column<TData>
}

export interface FilterListProps<TData = unknown>
  extends Omit<ComponentPropsWithoutRef<'div'>, 'children'> {
  children?: ReactNode | ((props: FilterListRenderProps<TData>) => ReactNode)
}

/**
 * Container for filter items.
 * Renders a `<div>` element.
 *
 * Documentation: [Bazza UI Filter](https://bazza-ui.com/docs/components/filter)
 */
const FilterList = forwardRef<HTMLDivElement, FilterListProps>(
  ({ className, children, ...props }, ref) => {
    const { filters, columns } = useFilterContext()

    // If regular children provided, just render them
    if (children && typeof children !== 'function') {
      return (
        <div
          ref={ref}
          data-slot="filter-list"
          className={cn('contents', className)}
          {...props}
        >
          {children}
        </div>
      )
    }

    // If no render function provided, just render the container
    if (!children) {
      return (
        <div
          ref={ref}
          data-slot="filter-list"
          className={cn('contents', className)}
          {...props}
        />
      )
    }

    // Otherwise, map over filters with render function
    const renderFn = children as (props: FilterListRenderProps) => ReactNode

    return (
      <div
        ref={ref}
        data-slot="filter-list"
        className={cn('contents', className)}
        {...props}
      >
        {filters.map((filter) => {
          const id = filter.columnId
          const column = getColumn(columns, id)

          // Skip if no filter value
          if (!filter.values) return null

          return (
            <div key={`filter-item-${filter.columnId}`}>
              {renderFn({ filter, column })}
            </div>
          )
        })}
      </div>
    )
  },
)

FilterList.displayName = 'FilterList'

export { FilterList }

export namespace FilterList {
  export type Props<TData = unknown> = FilterListProps<TData>
  export type RenderProps<TData = unknown> = FilterListRenderProps<TData>
}

'use client'

import {
  type ComponentPropsWithoutRef,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react'
import { cn } from '@/lib/utils'

export interface FilterListMobileContainerProps
  extends ComponentPropsWithoutRef<'div'> {
  children: React.ReactNode
}

/**
 * A scrollable container for filter blocks on mobile devices.
 * Renders a `<div>` element with horizontal scroll and blur effects.
 *
 * Documentation: [Bazza UI Filter](https://bazza-ui.com/docs/components/filter)
 */
const FilterListMobileContainer = forwardRef<
  HTMLDivElement,
  FilterListMobileContainerProps
>(({ children, className, ...props }, ref) => {
  const containerRef = useRef<HTMLDivElement>(null)
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const [showLeftBlur, setShowLeftBlur] = useState(false)
  const [showRightBlur, setShowRightBlur] = useState(true)

  useImperativeHandle(ref, () => containerRef.current!)

  // Check if there's content to scroll and update blur states
  const checkScroll = () => {
    if (scrollContainerRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } =
        scrollContainerRef.current

      // Show left blur if scrolled to the right
      setShowLeftBlur(scrollLeft > 0)

      // Show right blur if there's more content to scroll to the right
      // Add a small buffer (1px) to account for rounding errors
      setShowRightBlur(scrollLeft + clientWidth < scrollWidth - 1)
    }
  }

  // Set up ResizeObserver to monitor container size
  // biome-ignore lint/correctness/useExhaustiveDependencies: only run on mount
  useEffect(() => {
    if (scrollContainerRef.current) {
      const resizeObserver = new ResizeObserver(() => {
        checkScroll()
      })
      resizeObserver.observe(scrollContainerRef.current)
      return () => {
        resizeObserver.disconnect()
      }
    }
  }, [])

  // Update blur states when children change
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-check on children change
  useEffect(() => {
    checkScroll()
  }, [children])

  return (
    <div
      ref={containerRef}
      data-slot="filter-list-mobile-container"
      className={cn('relative w-full overflow-x-hidden', className)}
      {...props}
    >
      {/* Left blur effect */}
      {showLeftBlur && (
        <div className="absolute left-0 top-0 bottom-0 w-16 z-10 pointer-events-none bg-gradient-to-r from-background to-transparent animate-in fade-in-0" />
      )}

      {/* Scrollable container */}
      <div
        ref={scrollContainerRef}
        className="flex gap-2 overflow-x-scroll no-scrollbar"
        onScroll={checkScroll}
      >
        {children}
      </div>

      {/* Right blur effect */}
      {showRightBlur && (
        <div className="absolute right-0 top-0 bottom-0 w-16 z-10 pointer-events-none bg-gradient-to-l from-background to-transparent animate-in fade-in-0 " />
      )}
    </div>
  )
})

