import type { DateRange } from 'react-day-picker'
import { Calendar } from '@/components/ui/calendar'
import { Command, CommandGroup, CommandList } from '@/components/ui/command'
import type { FilterValueControllerProps } from './types'

export function FilterValueDateController<TData>({
  filter,
  column,
  actions,
}: FilterValueControllerProps<TData, 'date'>) {
  const [date, setDate] = useState<DateRange | undefined>({
    from: filter?.values[0] ?? new Date(),
    to: filter?.values[1] ?? undefined,
  })

  function changeDateRange(value: DateRange | undefined) {
    const start = value?.from
    const end =
      start && value && value.to && !isEqual(start, value.to)
        ? value.to
        : undefined

    setDate({ from: start, to: end })

    const isRange = start && end
    const newValues = isRange ? [start, end] : start ? [start] : []

    actions.setFilterValue(column, newValues)
  }

  return (
    <Command>
      <CommandList className="max-h-fit">
        <CommandGroup>
          <div>
            <Calendar
              mode="range"
              defaultMonth={date?.from}
              selected={date}
              onSelect={changeDateRange}
              numberOfMonths={1}
            />
          </div>
        </CommandGroup>
      </CommandList>
    </Command>
  )
}

'use client'

import type { Column } from '@bazza-ui/filters'
import {
  createNumberRange,
  type MinMaxReturn,
  numberFilterOperators,
  t,
} from '@bazza-ui/filters'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { Command, CommandGroup, CommandList } from '@/components/ui/command'
import { Slider } from '@/components/ui/slider'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { useDebounceCallback } from '../../hooks/use-debounce-callback'
import { DebouncedInput } from '../../ui/debounced-input'
import type { FilterValueControllerProps } from './types'

export function FilterValueNumberController<TData>({
  filter,
  column,
  actions,
  locale = 'en',
}: FilterValueControllerProps<TData, 'number'>) {
  const minMax = useMemo(
    () => column.getFacetedMinMaxValues() as MinMaxReturn<'number'>,
    [column],
  )
  const [sliderMin, sliderMax] = [
    minMax ? minMax[0] : 0,
    minMax ? minMax[1] : 0,
  ]

  // Local state for values
  const [values, setValues] = useState(filter?.values ?? [0, 0])

  // Sync with parent filter changes
  useEffect(() => {
    if (
      filter?.values &&
      filter.values.length === values.length &&
      filter.values.every((v, i) => v === values[i])
    ) {
      setValues(filter.values)
    }
  }, [filter?.values, values])

  const isNumberRange =
    filter && numberFilterOperators[filter.operator].target === 'multiple'

  const setFilterOperatorDebounced = useDebounceCallback(
    actions.setFilterOperator,
    500,
  )

  // Create a typed wrapper for setFilterValue to avoid 'as any' casts
  const setNumberFilterValue = useCallback(
    (col: Column<TData, 'number'>, vals: number[]) => {
      actions.setFilterValue(col, vals)
    },
    [actions],
  )
  const setFilterValueDebounced = useDebounceCallback(setNumberFilterValue, 500)

  const changeNumber = (value: number[]) => {
    setValues(value)
    setFilterValueDebounced(column, value)
  }

  const changeMinNumber = (value: number) => {
    const newValues = createNumberRange([value, values[1]!])
    setValues(newValues)
    setFilterValueDebounced(column, newValues)
  }

  const changeMaxNumber = (value: number) => {
    const newValues = createNumberRange([values[0]!, value])
    setValues(newValues)
    setFilterValueDebounced(column, newValues)
  }

  const changeType = useCallback(
    (type: 'single' | 'range') => {
      let newValues: number[] = []
      if (type === 'single')
        newValues = [values[0]!] // Keep the first value for single mode
      else if (!minMax)
        newValues = createNumberRange([values[0]!, values[1] ?? 0])
      else {
        const value = values[0]!
        newValues =
          value - minMax[0] < minMax[1] - value
            ? createNumberRange([value, minMax[1]])
            : createNumberRange([minMax[0], value])
      }

      const newOperator = type === 'single' ? 'is' : 'is between'

      // Update local state
      setValues(newValues)

      // Cancel in-flight debounced calls to prevent flicker/race conditions
      setFilterOperatorDebounced.cancel()
      setFilterValueDebounced.cancel()

      // Update global filter state atomically
      actions.setFilterOperator(column.id, newOperator)
      actions.setFilterValue(column, newValues)
    },
    [values, column, actions, minMax],
  )

  return (
    <div className="flex flex-col w-[315px] p-4">
      <Tabs
        value={isNumberRange ? 'range' : 'single'}
        onValueChange={(v) => changeType(v as 'single' | 'range')}
      >
        <TabsList className="w-full *:text-xs">
          <TabsTrigger value="single">{t('single', locale)}</TabsTrigger>
          <TabsTrigger value="range">{t('range', locale)}</TabsTrigger>
        </TabsList>
        <TabsContent value="single" className="flex flex-col gap-4 mt-4">
          {minMax && (
            <Slider
              value={[values[0]!]}
              onValueChange={(value) => changeNumber(value)}
              min={sliderMin}
              max={sliderMax}
              step={1}
              aria-orientation="horizontal"
            />
          )}
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium">{t('value', locale)}</span>
            <DebouncedInput
              id="single"
              type="number"
              value={values[0]!.toString()}
              onChange={(v) => changeNumber([Number(v)])}
            />
          </div>
        </TabsContent>
        <TabsContent value="range" className="flex flex-col gap-4 mt-4">
          {minMax && (
            <Slider
              value={values}
              onValueChange={changeNumber}
              min={sliderMin}
              max={sliderMax}
              step={1}
              aria-orientation="horizontal"
            />
          )}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex items-center gap-2">
              <span className="text-xs font-medium">{t('min', locale)}</span>
              <DebouncedInput
                type="number"
                value={values[0]!}
                onChange={(v) => changeMinNumber(Number(v))}
              />
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs font-medium">{t('max', locale)}</span>
              <DebouncedInput
                type="number"
                value={values[1]!}
                onChange={(v) => changeMaxNumber(Number(v))}
              />
            </div>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  )
}

/*
 * Source: https://usehooks-ts.com/react-hook/use-debounce-callback
 */

import { useEffect, useMemo, useRef } from 'react'
import { debounce } from '../lib/debounce'
import { useUnmount } from './use-unmount'

type DebounceOptions = {
  leading?: boolean
  trailing?: boolean
  maxWait?: number
}

type ControlFunctions = {
  cancel: () => void
  flush: () => void
  isPending: () => boolean
}

export type DebouncedState<T extends (...args: any) => ReturnType<T>> = ((
  ...args: Parameters<T>
) => ReturnType<T> | undefined) &
  ControlFunctions

export function useDebounceCallback<T extends (...args: any) => ReturnType<T>>(
  func: T,
  delay = 500,
  options?: DebounceOptions,
): DebouncedState<T> {
  const debouncedFunc = useRef<ReturnType<typeof debounce>>(null)

  useUnmount(() => {
    if (debouncedFunc.current) {
      debouncedFunc.current.cancel()
    }
  })

  const debounced = useMemo(() => {
    const debouncedFuncInstance = debounce(func, delay, options)

    const wrappedFunc: DebouncedState<T> = (...args: Parameters<T>) => {
      return debouncedFuncInstance(...args)
    }

    wrappedFunc.cancel = () => {
      debouncedFuncInstance.cancel()
    }

    wrappedFunc.isPending = () => {
      return !!debouncedFunc.current
    }

    wrappedFunc.flush = () => {
      return debouncedFuncInstance.flush()
    }

    return wrappedFunc
  }, [func, delay, options])

  // Update the debounced function ref whenever func, wait, or options change
  useEffect(() => {
    debouncedFunc.current = debounce(func, delay, options)
  }, [func, delay, options])

  return debounced
}

'use client'

import type {
  Column,
  ColumnDataType,
  DataTableFilterActions,
  FilterModel,
  FilterStrategy,
  Locale,
} from '@bazza-ui/filters'
import { useFilterItemContext } from '../components/item/filter-item'
import type { FilterVariant } from '../components/root/filter-context'
import {
  useFilterActions,
  useFilterLocale,
  useFilterStrategy,
  useFilterVariant,
} from '../components/root/filter-context'

/**
 * Input props for the resolution hook.
 * All props are optional - they will be resolved from context if not provided.
 */
export interface UseResolvedFilterPropsInput<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
> {
  column?: Column<TData, TType>
  filter?: FilterModel<TType>
  actions?: DataTableFilterActions
  strategy?: FilterStrategy
  locale?: Locale
  entityName?: string
  variant?: FilterVariant
}

/**
 * Base resolved props that are always available after resolution.
 */
export interface ResolvedFilterPropsBase {
  actions: DataTableFilterActions
  locale: Locale
  variant: FilterVariant
}

/**
 * Resolved props when column and filter are required.
 */
export interface ResolvedFilterPropsWithColumnAndFilter<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
> extends ResolvedFilterPropsBase {
  column: Column<TData, TType>
  filter: FilterModel<TType>
  strategy: FilterStrategy
  entityName?: string
}

/**
 * Resolved props when only column is required.
 */
export interface ResolvedFilterPropsWithColumn<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
> extends ResolvedFilterPropsBase {
  column: Column<TData, TType>
  entityName?: string
}

/**
 * Resolved props when only actions are required.
 */
export interface ResolvedFilterPropsWithActions
  extends ResolvedFilterPropsBase {
  filter: FilterModel
}

/**
 * Hook to resolve filter-related props from explicit props or context.
 * Reduces boilerplate in FilterOperator, FilterRemove, FilterSubject, FilterValue.
 *
 * @returns The resolved props, or null if required props are missing
 */
export function useResolvedFilterProps<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
>(
  props: UseResolvedFilterPropsInput<TData, TType>,
): ResolvedFilterPropsWithColumnAndFilter<TData, TType> | null {
  const itemContext = useFilterItemContext<TData, TType>()
  const filterActions = useFilterActions()
  const filterStrategy = useFilterStrategy()
  const filterLocale = useFilterLocale()
  const contextVariant = useFilterVariant()

  const column = props.column ?? itemContext?.column
  const filter = props.filter ?? itemContext?.filter
  const actions = props.actions ?? itemContext?.actions ?? filterActions
  const strategy = props.strategy ?? itemContext?.strategy ?? filterStrategy
  const locale = props.locale ?? itemContext?.locale ?? filterLocale ?? 'en'
  const entityName = props.entityName ?? itemContext?.entityName
  const variant = props.variant ?? contextVariant ?? 'default'

  if (!column || !filter || !actions || !strategy) {
    return null
  }

  return {
    column,
    filter,
    actions,
    strategy,
    locale,
    entityName,
    variant,
  }
}

/**
 * Hook to resolve filter props when only column is required.
 * Used by FilterSubject which doesn't need filter or actions.
 */
export function useResolvedColumnProps<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
>(
  props: Pick<
    UseResolvedFilterPropsInput<TData, TType>,
    'column' | 'entityName' | 'variant'
  >,
): ResolvedFilterPropsWithColumn<TData, TType> | null {
  const itemContext = useFilterItemContext<TData, TType>()
  const filterLocale = useFilterLocale()
  const filterActions = useFilterActions()
  const contextVariant = useFilterVariant()

  const column = props.column ?? itemContext?.column
  const entityName = props.entityName ?? itemContext?.entityName
  const variant = props.variant ?? contextVariant ?? 'default'
  const locale = itemContext?.locale ?? filterLocale ?? 'en'
  const actions = itemContext?.actions ?? filterActions

  if (!column || !actions) {
    return null
  }

  return {
    column,
    actions,
    locale,
    entityName,
    variant,
  }
}

/**
 * Hook to resolve filter props when only filter and actions are required.
 * Used by FilterRemove which doesn't need column.
 */
export function useResolvedFilterActionsProps(
  props: Pick<UseResolvedFilterPropsInput, 'filter' | 'actions' | 'variant'>,
): ResolvedFilterPropsWithActions | null {
  const itemContext = useFilterItemContext()
  const filterActions = useFilterActions()
  const filterLocale = useFilterLocale()
  const contextVariant = useFilterVariant()

  const filter = props.filter ?? itemContext?.filter
  const actions = props.actions ?? itemContext?.actions ?? filterActions
  const variant = props.variant ?? contextVariant ?? 'default'
  const locale = itemContext?.locale ?? filterLocale ?? 'en'

  if (!filter || !actions) {
    return null
  }

  return {
    filter,
    actions,
    locale,
    variant,
  }
}

/*
 * Source: https://usehooks-ts.com/react-hook/use-unmount
 */

import { useEffect, useRef } from 'react'

export function useUnmount(func: () => void) {
  const funcRef = useRef(func)

  funcRef.current = func

  useEffect(
    () => () => {
      funcRef.current()
    },
    [],
  )
}

type ControlFunctions = {
  cancel: () => void
  flush: () => void
  isPending: () => boolean
}

type DebounceOptions = {
  leading?: boolean
  trailing?: boolean
  maxWait?: number
}

export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number,
  options: DebounceOptions = {},
): ((...args: Parameters<T>) => ReturnType<T> | undefined) & ControlFunctions {
  const { leading = false, trailing = true, maxWait } = options
  let timeout: NodeJS.Timeout | null = null
  let lastArgs: Parameters<T> | null = null
  let lastThis: any
  let result: ReturnType<T> | undefined
  let lastCallTime: number | null = null
  let lastInvokeTime = 0

  const maxWaitTime = maxWait !== undefined ? Math.max(wait, maxWait) : null

  function invokeFunc(time: number): ReturnType<T> | undefined {
    if (lastArgs === null) return undefined
    const args = lastArgs
    const thisArg = lastThis
    lastArgs = null
    lastThis = null
    lastInvokeTime = time
    result = func.apply(thisArg, args)
    return result
  }

  function shouldInvoke(time: number): boolean {
    if (lastCallTime === null) return false
    const timeSinceLastCall = time - lastCallTime
    const timeSinceLastInvoke = time - lastInvokeTime
    return (
      lastCallTime === null ||
      timeSinceLastCall >= wait ||
      timeSinceLastCall < 0 ||
      (maxWaitTime !== null && timeSinceLastInvoke >= maxWaitTime)
    )
  }

  function startTimer(
    pendingFunc: () => void,
    waitTime: number,
  ): NodeJS.Timeout {
    return setTimeout(pendingFunc, waitTime)
  }

  function remainingWait(time: number): number {
    if (lastCallTime === null) return wait
    const timeSinceLastCall = time - lastCallTime
    const timeSinceLastInvoke = time - lastInvokeTime
    const timeWaiting = wait - timeSinceLastCall
    return maxWaitTime !== null
      ? Math.min(timeWaiting, maxWaitTime - timeSinceLastInvoke)
      : timeWaiting
  }

  function timerExpired() {
    const time = Date.now()
    if (shouldInvoke(time)) {
      return trailingEdge(time)
    }
    timeout = startTimer(timerExpired, remainingWait(time))
  }

  function leadingEdge(time: number): ReturnType<T> | undefined {
    lastInvokeTime = time
    timeout = startTimer(timerExpired, wait)
    return leading ? invokeFunc(time) : undefined
  }

  function trailingEdge(time: number): ReturnType<T> | undefined {
    timeout = null
    if (trailing && lastArgs) {
      return invokeFunc(time)
    }
    lastArgs = null
    lastThis = null
    return result
  }

  function debounced(
    this: any,
    ...args: Parameters<T>
  ): ReturnType<T> | undefined {
    const time = Date.now()
    const isInvoking = shouldInvoke(time)

    lastArgs = args
    lastThis = this
    lastCallTime = time

    if (isInvoking) {
      if (timeout === null) {
        return leadingEdge(lastCallTime)
      }
      if (maxWaitTime !== null) {
        timeout = startTimer(timerExpired, wait)
        return invokeFunc(lastCallTime)
      }
    }
    if (timeout === null) {
      timeout = startTimer(timerExpired, wait)
    }
    return result
  }

  debounced.cancel = () => {
    if (timeout !== null) {
      clearTimeout(timeout)
    }
    lastInvokeTime = 0
    lastArgs = null
    lastThis = null
    lastCallTime = null
    timeout = null
  }

  debounced.flush = () => {
    return timeout === null ? result : trailingEdge(Date.now())
  }

  debounced.isPending = () => {
    return timeout !== null
  }

  return debounced
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { Input } from '@/components/ui/input'
import { debounce } from '../lib/debounce'

export function DebouncedInput({
  value: initialValue,
  onChange,
  debounceMs = 500, // This is the wait time, not the function
  ...props
}: {
  value: string | number
  onChange: (value: string | number) => void
  debounceMs?: number
} & Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange'>) {
  const [value, setValue] = useState(initialValue)

  // Sync with initialValue when it changes
  useEffect(() => {
    setValue(initialValue)
  }, [initialValue])

  // Define the debounced function with useCallback
  const debouncedOnChange = useCallback(
    debounce((newValue: string | number) => {
      onChange(newValue)
    }, debounceMs), // Pass the wait time here
    [debounceMs, onChange], // Dependencies
  )

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value
    setValue(newValue) // Update local state immediately
    debouncedOnChange(newValue) // Call debounced version
  }

  return <Input {...props} value={value} onChange={handleChange} />
}
